// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x123);
        // First, call owned() as owner (which is address(this) initially) to satisfy the precondition
        c.owned();
        // Now, attempt to call transferOwnership from nonOwner
        vm.prank(nonOwner);
        // In reference, this reverts; in mutant, it succeeds
        bool ok;
        try c.transferOwnership(address(0x456)) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract returns false (revert), the buggy contract returns true (no revert)
        // We assert that the behavior matches the reference: should revert, so ok should be false
        assertTrue(!ok);
    }
}

