pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(0x1);
        address nonOwner = address(0x2);
        address newOwner = address(0x3);

        // Set initial owner
        vm.prank(owner);
        c.transferOwnership(owner);

        // Call owned() from owner
        vm.prank(owner);
        c.owned();

        // Attempt to transfer ownership from non-owner
        vm.prank(nonOwner);
        c.transferOwnership(newOwner);

        // In reference, owner unchanged; in mutant, owner becomes newOwner
        assertTrue(c.owner() == owner);
    }
}

