// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up owner and non-owner addresses
        address owner = address(0x1);
        address nonOwner = address(0x2);
        address newOwner = address(0x3);

        // Set initial owner
        vm.prank(owner);
        c.transferOwnership(owner);

        // Owner calls owned()
        vm.prank(owner);
        c.owned();

        // Non-owner attempts to transfer ownership
        vm.prank(nonOwner);
        // Try-catch to observe revert behavior
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference, owner unchanged (non-owner call reverts)
        // In buggy version, owner changes to newOwner
        assertTrue((ok == false) && (c.owner() == owner));
    }
}

